package os.aios.core.workspace;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.*;

/** AIOS-visible records independent of a provider's private thread database. */
final class StandardRecords{
 private final WorkspaceStore store;private final SQLiteDatabase db;StandardRecords(WorkspaceStore s,SQLiteDatabase d){store=s;db=d;}
 static void migrate(SQLiteDatabase d){
  d.execSQL("CREATE TABLE IF NOT EXISTS harnesses(id TEXT NOT NULL,version INTEGER NOT NULL,capabilities TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(id,version))");
  d.execSQL("CREATE TABLE IF NOT EXISTS standard_sessions(id TEXT PRIMARY KEY,task_id TEXT,active_execution_id TEXT,state TEXT NOT NULL,harness_id TEXT NOT NULL,harness_version INTEGER NOT NULL,native_thread_id TEXT NOT NULL,import_cursor TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(harness_id,native_thread_id))");
  d.execSQL("CREATE TABLE IF NOT EXISTS standard_records(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES standard_sessions(id) ON DELETE CASCADE,execution_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('user','assistant','tool_request','tool_result','approval','takeover','status')),sequence INTEGER NOT NULL,body TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(session_id,source_id,source_version))");
  d.execSQL("CREATE INDEX IF NOT EXISTS standard_records_order ON standard_records(session_id,sequence,id)");
  d.execSQL("CREATE TABLE IF NOT EXISTS execution_receipts(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,request_id TEXT NOT NULL,param_fingerprint TEXT NOT NULL,state TEXT NOT NULL,side_effect TEXT NOT NULL,receipt TEXT NOT NULL DEFAULT '{}',generation INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(session_id,request_id))");
 }
 void importCodexSnapshot(String workspaceSession,String generation)throws Exception{
  JSONObject projected=store.require(db,"sessions",workspaceSession);String thread=projected.getString("source_id");JSONArray items=store.rows(db,"SELECT * FROM sync_items WHERE session_id=? AND generation=? ORDER BY sequence",workspaceSession,generation);
  for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String role=item.getString("role"),kind=role.equals("user")?"user":role.equals("assistant")?"assistant":"tool_result";importEvent(new JSONObject().put("harness_id","codex-app-server").put("harness_version",1).put("native_thread_id",thread).put("execution_id",item.optString("turn_id")).put("source_id",item.getString("id")).put("source_version",generation).put("kind",kind).put("body",item.getString("content_md")).put("created_at",item.getLong("created_at")).put("cursor",Long.toString(item.getLong("sequence"))));}
 }
 JSONObject call(String op,JSONObject p)throws Exception{
  if(op.equals("runtime.harness.register")){String id=p.getString("harness_id");int version=p.getInt("version");ContentValues v=new ContentValues();v.put("id",id);v.put("version",version);v.put("capabilities",p.getJSONObject("capabilities").toString());v.put("updated_at",WorkspaceStore.now());db.insertWithOnConflict("harnesses",null,v,SQLiteDatabase.CONFLICT_REPLACE);return new JSONObject().put("harness_id",id).put("version",version);}
  if(op.equals("runtime.harness.list"))return new JSONObject().put("items",store.rows(db,"SELECT * FROM harnesses ORDER BY id,version DESC"));
  if(op.equals("runtime.session.import"))return importEvent(p);
  if(op.equals("runtime.session.switch"))return switchHarness(p);
  if(op.equals("runtime.history.export")){String id=p.getString("session_id");JSONObject session=store.require(db,"standard_sessions",id);return session.put("records",store.rows(db,"SELECT * FROM standard_records WHERE session_id=? ORDER BY sequence,id",id)).put("portable_state","visible_history_only");}
  if(op.equals("runtime.execution.record"))return receipt(p);
  if(op.equals("runtime.execution.get"))return store.require(db,"execution_receipts",p.getString("id"));
  throw new IllegalArgumentException("Unknown runtime record action");
 }
 private JSONObject switchHarness(JSONObject p)throws Exception{String sessionId=p.getString("session_id"),harness=p.getString("harness_id");int version=p.getInt("harness_version");JSONObject session=store.require(db,"standard_sessions",sessionId);JSONArray adapter=store.rows(db,"SELECT * FROM harnesses WHERE id=? AND version=?",harness,Integer.toString(version));if(adapter.length()==0)throw new IllegalArgumentException("Harness adapter is not registered");int unknown=store.rows(db,"SELECT count(*) AS n FROM execution_receipts WHERE session_id=? AND state IN ('submitting','running','outcome_unknown')",sessionId).getJSONObject(0).getInt("n");if(unknown>0)throw new IllegalStateException("Execution has unresolved side effects; reconcile before switching Harness");JSONObject history=call("runtime.history.export",new JSONObject().put("session_id",sessionId));String execution=WorkspaceStore.id();db.execSQL("UPDATE standard_sessions SET active_execution_id=?,state='switching',harness_id=?,harness_version=?,native_thread_id='',updated_at=? WHERE id=?",new Object[]{execution,harness,version,WorkspaceStore.now(),sessionId});return new JSONObject().put("session_id",sessionId).put("execution_id",execution).put("harness_id",harness).put("harness_version",version).put("portable_state","visible_history_only").put("history",history.getJSONArray("records"));}
 private JSONObject importEvent(JSONObject p)throws Exception{
  String harness=p.getString("harness_id"),nativeThread=p.getString("native_thread_id"),source=p.getString("source_id"),version=p.getString("source_version");JSONArray existing=store.rows(db,"SELECT * FROM standard_sessions WHERE harness_id=? AND native_thread_id=?",harness,nativeThread);String session;
  if(existing.length()==0){session=WorkspaceStore.id();db.execSQL("INSERT INTO standard_sessions(id,task_id,active_execution_id,state,harness_id,harness_version,native_thread_id,import_cursor,created_at,updated_at) VALUES(?,NULL,?,'running',?,?,?,?,?,?)",new Object[]{session,p.optString("execution_id"),harness,p.getInt("harness_version"),nativeThread,p.optString("cursor",""),WorkspaceStore.now(),WorkspaceStore.now()});}else session=existing.getJSONObject(0).getString("id");
  JSONArray duplicate=store.rows(db,"SELECT * FROM standard_records WHERE session_id=? AND source_id=? AND source_version=?",session,source,version);if(duplicate.length()>0){JSONObject old=duplicate.getJSONObject(0);db.execSQL("UPDATE standard_records SET body=?,execution_id=?,created_at=? WHERE id=?",new Object[]{p.optString("body",""),p.optString("execution_id"),p.optLong("created_at",WorkspaceStore.now()),old.getString("id")});return store.require(db,"standard_records",old.getString("id")).put("updated",true);}
  String kind=p.getString("kind");if(!java.util.Set.of("user","assistant","tool_request","tool_result","approval","takeover","status").contains(kind))throw new IllegalArgumentException("Invalid record kind");long sequence=store.rows(db,"SELECT COALESCE(MAX(sequence),0)+1 AS n FROM standard_records WHERE session_id=?",session).getJSONObject(0).getLong("n");String id=WorkspaceStore.id();db.execSQL("INSERT INTO standard_records VALUES(?,?,?,?,?,?,?,?,?)",new Object[]{id,session,p.optString("execution_id"),kind,sequence,p.optString("body",""),source,version,p.optLong("created_at",WorkspaceStore.now())});db.execSQL("UPDATE standard_sessions SET import_cursor=?,updated_at=? WHERE id=?",new Object[]{p.optString("cursor",""),WorkspaceStore.now(),session});return store.require(db,"standard_records",id).put("standard_session_id",session);
 }
 private JSONObject receipt(JSONObject p)throws Exception{
  String session=p.getString("session_id"),request=p.getString("request_id"),fingerprint=p.getString("param_fingerprint"),state=p.getString("state");os.aios.runtime.CoreContracts.parseState(state);JSONArray old=store.rows(db,"SELECT * FROM execution_receipts WHERE session_id=? AND request_id=?",session,request);if(old.length()>0){JSONObject row=old.getJSONObject(0);if(!row.getString("param_fingerprint").equals(fingerprint))throw new IllegalArgumentException("request_id reused with different parameters");os.aios.runtime.CoreContracts.requireTransition(row.getString("state"),state);db.execSQL("UPDATE execution_receipts SET state=?,receipt=?,generation=generation+1,updated_at=? WHERE id=?",new Object[]{state,p.optJSONObject("receipt")==null?"{}":p.getJSONObject("receipt").toString(),WorkspaceStore.now(),row.getString("id")});return store.require(db,"execution_receipts",row.getString("id"));}
  String id=WorkspaceStore.id();db.execSQL("INSERT INTO execution_receipts(id,session_id,request_id,param_fingerprint,state,side_effect,receipt,generation,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,?,?)",new Object[]{id,session,request,fingerprint,state,p.getString("side_effect"),p.optJSONObject("receipt")==null?"{}":p.getJSONObject("receipt").toString(),WorkspaceStore.now(),WorkspaceStore.now()});return store.require(db,"execution_receipts",id);
 }
}
